122: import { categoryName, categoryScope, stockOrder, send } from './helpers.js';
123: 
124: export async function inventoryList(db, input) {
125:   const order = stockOrder(input.sort);
126:   return db.query('SELECT p.sku,p.title,COALESCE(SUM(b.on_hand-b.reserved),0) available FROM products p LEFT JOIN bins b ON b.sku=p.sku GROUP BY p.sku ORDER BY ' + order, {});
127: }
128: export async function categorySnapshot(db, request) {
129:   const category = categoryName(request.category);
130:   const scope = categoryScope(category);
131:   const rows = await db.query('SELECT p.category,COUNT(*) count,COALESCE(SUM(b.on_hand),0) units FROM products p LEFT JOIN bins b ON b.sku=p.sku WHERE ' + scope + ' GROUP BY p.category', {});
132:   return rows.map(row => ({...row, empty:row.units===0}));
133: }
134: export async function purgeReservation(db, id) {
135:   const result = await send(db, 'DELETE FROM reservations WHERE id=:id', {id});
136:   return {deleted:result.changes};
137: }

1: import { sql, bind } from '@mk3008/serene';
2: 
3: import * as store from './store.js';
4: 
5: export async function browse(db, query) { return {status:200,body:await store.inventoryList(db,query)}; }
6: export async function card(db, params) {
7:   const [product]=await store.product(db,params.sku);
8:   return product ? {status:200,body:{product,bins:await store.binLevels(db,params.sku)}} : {status:404,body:{error:'missing'}};
9: }
10: export async function receive(db, body) {
11:   await store.insertReceipt(db,body);
12:   for (const item of body.items||[]) await store.receiptLine(db,body.id,item.sku,item.quantity,item.unitCostCents);
13:   return {status:201,body:{id:body.id}};
14: }
15: export async function inventoryReport(db, query) { return {status:200,body:await store.categorySnapshot(db,query)}; }

